// Demo source content. PRODUCTION: replace with webhook body or CMS fetch.
const sample = {
  title: "The Most Profitable n8n Automation Nobody Talks About: Invoice Data Entry",
  body: "Everyone wants to build AI chatbots. Nobody wants to automate invoice data entry. That's exactly why it's the most profitable n8n automation you can build. Finance teams spend 3-6 hours per week manually typing invoice data. I built a workflow that watches Gmail for invoice PDFs, extracts every field with AI, catches duplicates, and flags anomalies. It caught a $757 duplicate payment on day one. Boring = profitable.",
  platforms: ["twitter", "linkedin", "hook"]
};
const input = $json.body && $json.body.title ? $json.body : sample;
return { json: { ...input, EventKey: "content:" + (input.title || 'untitled').slice(0,40) + ":" + new Date().toISOString().slice(0,10) } };

const d = $json;
const ok = d.body && String(d.body).length > 100 && Array.isArray(d.platforms) && d.platforms.length > 0;
if (!ok) return { json: { Timestamp: new Date().toISOString(), EventKey: d.EventKey || 'unknown',
  Workflow: 'content-repurpose', Status: 'rejected_invalid_input', Reason: 'body too short or no platforms' } };
return { json: { ...d, input_valid: true } };

const raw = $json.content?.parts?.filter(p => !p.thought).map(p => p.text || '').join('') ?? $json.text ?? '';
const cleaned = raw.replace(/```json/gi,'').replace(/```/g,'').trim();
let data = null;
for (const c of (cleaned.match(/\{[\s\S]*\}/g) || []).reverse()) {
  try { const p = JSON.parse(c); if (p && (p.twitter_thread || p.linkedin_post)) { data = p; break; } } catch(e){}
}
const src = $('Validate Input').item.json;
if (!data) return { json: { ...src, parse_ok: false, error: 'AI output unparseable' } };
const confidence = typeof data.confidence === 'number' ? data.confidence : 0.7;
return { json: { ...src, ...data, confidence, parse_ok: true } };

